    {
      "claim_id": "claim.a7f7ba358f7b8f4aadc66d7f",
      "candidate_id": "node.68f8e39cf8e43c95a1e0890d",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u60.8163",
            "quote": "BDCs are close-ended funds registered under the US Investment Company Act of 1940, which primarily invest in debt and equity of small and mid-sized companies in the US."
          }
        ],
        "rationale": "The claim faithfully reports the circular's description; it does not independently establish US statutory treatment."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "4f10da87ddb322d03b098a5b1c69788f047e6978f5ae63ea518a5ed15a2de392",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u1.5",
            "quote": "indirect exposures2 including through investments in business development companies (BDCs)3, collateralised loan obligations (CLOs)4 or financial derivative instruments5."
          }
        ],
        "rationale": "The description helps identify a possible source of indirect exposure used in the classification threshold. BDC status is not itself an automatic classification trigger."
      },
      "executable_correspondence": {
        "status": "OMITS",
        "representation_quotes": [
          "Supplying this fact requires resolving applicable exposure measurement and aggregation; missing holdings or measurement evidence is not false."
        ],
        "rationale": "The formula accepts an aggregate threshold fact without implementing the BDC description or deciding how a BDC investment contributes to exposure. This upstream omission does not by itself establish a defect in the Boolean classification rule."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "No additional external authority is needed to establish what the circular describes. Independent verification of US legal status would be a separate inquiry."
      },
      "followup_questions": []
    },
    {
      "claim_id": "claim.ae70d5959e88ef0af314b6c1",
      "candidate_id": "node.68f8e39cf8e43c95a1e0890d",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u39.5617",
            "quote": "They should also ensure that the distributors chosen are appropriate for covering the target market identified, have the necessary product knowledge to understand the Fund (including whether the Fund is a complex product) and to assign an appropriate product risk rating (if applicable) for the Fund, and advise investors accordingly."
          }
        ],
        "rationale": "The passage supports the distributor-knowledge expectation, including the qualification on product risk ratings."
      },
      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "4f10da87ddb322d03b098a5b1c69788f047e6978f5ae63ea518a5ed15a2de392",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u39.5617",
            "quote": "have the necessary product knowledge to understand the Fund (including whether the Fund is a complex product)"
          }
        ],
        "rationale": "This expectation concerns distributor selection and knowledge of classification; it supplies neither a classification trigger nor an exclusion."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [
          "Result: at least one of these conditions holds: [the fact aggregate_private_market_exposure_at_least_half_nav; the fact applicable_sfc_complex_product_designation]"
        ],
        "rationale": "The candidate answers a classification question, not whether managers have satisfied distributor-selection expectations."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The quoted circular directly supports this narrow expectation. Interpreting the full incorporated product-approval requirements would require a separate external-authority assessment."
      },
      "followup_questions": []
    },
    {
      "claim_id": "claim.b05fc394e0a3540cb65b9b8b",
      "candidate_id": "node.68f8e39cf8e43c95a1e0890d",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u26.4290",
            "quote": "the extent, nature and characteristics of the specific asset types in which the Fund invests (eg, the tranches and credit ratings of CLOs; the structure, tranches and underlying assets of SRTs);"
          },
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "On a case-by-case basis, the SFC may also designate a Fund as a complex product, taking into account factors including, without limitation:"
          },
          {
            "unit_id": "d4148dd852cee.u64.8910",
            "quote": "In cases where the Fund’s aggregate direct and indirect exposures to private market assets are less than 50% of the Fund’s NAV."
          }
        ],
        "rationale": "Asset characteristics are non-exhaustive discretionary factors. Footnote 7 places the holistic designation assessment in the below-50% setting."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "4f10da87ddb322d03b098a5b1c69788f047e6978f5ae63ea518a5ed15a2de392",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u29.4630",
            "quote": "In assessing whether the complex product designation is warranted7, the SFC will adopt a holistic approach taking into account the specific circumstances of the case."
          }
        ],
        "rationale": "These factors explain the discretionary route relevant to the question, but their presence does not establish an actual designation."
      },
      "executable_correspondence": {
        "status": "OMITS",
        "representation_quotes": [
          "Mere risk factors, possible designation or an unsearched designation history do not establish a positive or negative value.",
          "Supplied classifications requiring judgment: listed_closed_ended_alternative_asset_fund, aggregate_private_market_exposure_at_least_half_nav, applicable_sfc_complex_product_designation. Their assessment is not implemented by this formula."
        ],
        "rationale": "The formula does not implement asset-characteristic assessment. It instead consumes an actual applicable designation, appropriately avoiding an automatic trigger based on a discretionary factor. The omission is not itself a classification defect."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The circular supplies the factor and its discretionary context; no additional authority is needed for this claim."
      },
      "followup_questions": []
    },
    {
      "claim_id": "claim.b29c1a0348164bd38b5d8b1b",
      "candidate_id": "node.68f8e39cf8e43c95a1e0890d",
      "source_support": {
