          }
        ],
        "rationale": "Footnote 2 expressly establishes both the open-ended examples and the possibility of updates."
      },
      "question_relation": {
        "status": "RELEVANT",
        "question_hash": "4f10da87ddb322d03b098a5b1c69788f047e6978f5ae63ea518a5ed15a2de392",
        "evidence": [
          {
            "unit_id": "d4148dd852cee.u21.3779",
            "quote": "A Fund will be considered as a complex product if its total direct and indirect exposures to private market assets amount to 50% or more of the Fund’s NAV."
          }
        ],
        "rationale": "Exposure aggregation must not exclude an investment merely because it is absent from the examples. Applicable updates could affect assessment-time input preparation."
      },
      "executable_correspondence": {
        "status": "OMITS",
        "representation_quotes": [
          "Whether established total direct and indirect exposure to private market assets amounts to at least 50% of the Fund's NAV at the assessment time.",
          "Supplying this fact requires resolving applicable exposure measurement and aggregation; missing holdings or measurement evidence is not false."
        ],
        "rationale": "The input description is broad and imposes no closed list, but executable exposure identification and update handling are absent. Compatibility with the claim does not establish executable preservation."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "Footnote 2 supports this claim without additional authority. Establishing whether a later update applies to a particular assessment would require that update."
      },
      "followup_questions": [
        "At the specified assessment time, had the SFC issued any applicable updates to the indirect-exposure examples? No such update or identifiable dependency mapping is supplied."
      ]
    },
    {
